CREATE TABLE IF NOT EXISTS employee_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES workforce_employees(id) ON DELETE CASCADE, movement_type text NOT NULL, from_position_id uuid REFERENCES org_positions(id), to_position_id uuid REFERENCES org_positions(id), effective_date date NOT NULL, reason text, approved_by uuid REFERENCES workforce_employees(id), status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());